def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    wall_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]
    wall_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    if wall_cols:
        wc = wall_cols[0]
        left, right = min(c for r, c in cells), max(c for r, c in cells)
        if wc < left:
            shift = wc + 1 - left
            edge = right + shift + 1
        else:
            shift = wc - 1 - right
            edge = left + shift - 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nc = c + shift
            if 0 <= nc < w and nc != wc:
                out[r][nc] = grid[r][c]
        if 0 <= edge < w and edge != wc:
            for r in range(h):
                out[r][edge] = 8
    elif wall_rows:
        wr = wall_rows[0]
        top, bottom = min(r for r, c in cells), max(r for r, c in cells)
        if wr < top:
            shift = wr + 1 - top
            edge = bottom + shift + 1
        else:
            shift = wr - 1 - bottom
            edge = top + shift - 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            nr = r + shift
            if 0 <= nr < h and nr != wr:
                out[nr][c] = grid[r][c]
        if 0 <= edge < h and edge != wr:
            out[edge] = [8] * w
    return out
